a<-commandArgs(TRUE);if(length(a)<2)stop("Usage: audit_artifacts.R <project> <out>");src<-normalizePath(a[1]);out<-a[2];dir.create(out,recursive=TRUE,showWarnings=FALSE);fs<-list.files(src,recursive=TRUE,full.names=TRUE,all.files=TRUE,no..=TRUE);info<-file.info(fs);fs<-fs[!info$isdir];info<-file.info(fs);rel<-substring(fs,nchar(src)+2L);manifest<-data.frame(file=rel,bytes=info$size,extension=tolower(tools::file_ext(fs)),md5=unname(tools::md5sum(fs)));write.csv(manifest,file.path(out,"artifact_manifest.csv"),row.names=FALSE);rd<-fs[grepl("\\.RData$",fs,ignore.case=TRUE)];obj<-list();for(f in rd){e<-new.env(parent=emptyenv());n<-load(f,envir=e);obj[[f]]<-do.call(rbind,lapply(sort(n),function(x){o<-e[[x]];data.frame(file=basename(f),object=x,class=paste(class(o),collapse="/"),dimensions=paste(dim(o),collapse="x"),bytes=as.numeric(object.size(o)))}))};if(length(obj))write.csv(do.call(rbind,obj),file.path(out,"rdata_objects.csv"),row.names=FALSE);csv<-fs[grepl("\\.csv$",fs,ignore.case=TRUE)];schemas<-do.call(rbind,lapply(csv,function(f){d<-read.csv(f,check.names=FALSE,nrows=5);data.frame(file=basename(f),columns=paste(names(d),collapse="|"))}));write.csv(schemas,file.path(out,"csv_schemas.csv"),row.names=FALSE)
